# frozen_string_literal: true

require_relative "../../plaid"

module Plaid
  module Types
    # The `inflow_model` allows you to model a test account that receives regular income or makes regular payments on a
    # loan. Any transactions generated by the `inflow_model` will appear in addition to randomly generated test data or
    # transactions specified by `override_accounts`.
    class InflowModel < Internal::Types::Model
      field :type, -> { String }, optional: false, nullable: false

      field :income_amount, -> { Float }, optional: true, nullable: false

      field :payment_day_of_month, -> { Object }, optional: true, nullable: false

      field :transaction_name, -> { String }, optional: true, nullable: false

      field :statement_day_of_month, -> { Object }, optional: true, nullable: false
    end
  end
end
